// Shared run matrix for the entity-detail pilots (Driver, Team, Circuit; 2026-11-09).
// Not a config: driver-detail.config.mjs, team-detail.config.mjs and
// circuit-detail.config.mjs call detailConfig() with their own pages, pointer
// states and data checks. The pages are generated by the approved generators
// (fixture data only); nothing here adds content.

// The detail app bar (shared component under test): title text, one-line ellipsis state, bar height.
export const DBAR = `(() => [...document.querySelectorAll('.dbar')].filter((b) => b.getClientRects().length).map((b) => { const t = b.querySelector('.dbar__title');
  return { title: t.textContent, ellipsized: t.scrollWidth > t.clientWidth + 1, h: Math.round(b.getBoundingClientRect().height * 100) / 100, sticky: getComputedStyle(b).position }; }))()`;

// Navigation: activates every hash link in document order and records the route each one opens.
// Main scenario pages contain only hash routes (asserted: no other link), so nothing leaves the page.
const LINK_LABEL = `(a) => (a.getAttribute('aria-label') || a.textContent.trim().replace(/\\s+/g, ' ')).slice(0, 60)`;
export const CLICK_ALL_LINKS = `(() => { const label = ${LINK_LABEL}; const links = [...document.querySelectorAll('a[href]')];
  const other = links.filter((a) => !a.getAttribute('href').startsWith('#')).map((a) => a.getAttribute('href'));
  const routes = links.filter((a) => a.getAttribute('href').startsWith('#')).map((a) => { a.click(); return [label(a), a.getAttribute('href'), location.hash]; });
  return { routes, other, file: location.pathname.split('/').pop() }; })()`;
export const NAV_STATE = `(() => ({ hash: location.hash, scrollY: Math.round(scrollY), file: location.pathname.split('/').pop() }))()`;
const NAV_ASSERT = [
  ['every-link-opens-its-own-route', (r) => r.links.routes.length > 0 && r.links.routes.every(([, href, hash]) => href === hash)],
  ['no-link-leaves-the-detail-page', (r) => r.links.other.length === 0 && r['enter-back'].file === r.links.file],
  ['enter-activates-back', (r) => r['enter-back'].hash === '#back'],
];

const LANGS = [['en', ''], ['es', '.es']];
const KEY_SIZES = [[390, 844, 100], [320, 693, 200]];

/**
 * @param {object} o
 * @param {string} o.name           config name
 * @param {string} o.baseline       approved folder, relative to tools/
 * @param {string} o.pilot          pilot folder, relative to tools/
 * @param {string[]} o.scenarios    main page stems (index, partial, …), all hash-routed
 * @param {Array} o.forced          [page stem, [[selector, 'hover'|'active'], …]] pointer states per page
 * @param {string} o.data           js expression returning the screen's data record
 * @param {object} o.dataAssert     { '<lang>-<stem>': [[label, (r) => bool], …] } checked on r.data in both versions
 * @param {object} o.probes         extra per-run probes
 * @param {object} [o.queries]      { stem: { label: 'query' } } static queries per scenario page (default: none)
 * @param {object[]} [o.extraPages] pages appended as is (e.g. a development-only stress page)
 * @param {object[]} [o.extraRuns]  runs appended as is
 * Options added 2026-11-10 (Grand Prix pilot); with their defaults the Driver, Team and Circuit runs are unchanged.
 */
export function detailConfig(o) {
  const pages = LANGS.flatMap(([lang, sfx]) => [
    ...o.scenarios.map((s) => ({ id: `${lang}-${s}`, file: `${s}${sfx}.html`, ...(o.queries?.[s] ? { queries: o.queries[s] } : {}) })),
    { id: `${lang}-states`, file: `states${sfx}.html`, capture: 'segments' },
  ]).concat(o.extraPages || []);
  const runs = [
    // Keyboard: Tab through every visible link and button (focus ring pixels + role / name / locator per stop).
    ...LANGS.flatMap(([lang]) => o.scenarios.flatMap((s) => KEY_SIZES.map(([w, h, scale]) =>
      ({ name: `${lang}-${s}-${w}x${h}-${scale}-focus`, page: `${lang}-${s}`, viewport: [w, h], scale, action: 'focus' })))),
    ...LANGS.map(([lang]) => ({ name: `${lang}-states-390x844-100-focus`, page: `${lang}-states`, viewport: [390, 844], action: 'focus' })),
    // Pointer: forced :hover / :active.
    ...LANGS.flatMap(([lang]) => o.forced.map(([s, states]) =>
      ({ name: `${lang}-${s}-390x844-100-pointer`, page: `${lang}-${s}`, viewport: [390, 844], action: 'forced', states }))),
    // Navigation: every route, and Enter on the back action.
    ...LANGS.flatMap(([lang]) => o.scenarios.map((s) => ({ name: `${lang}-${s}-390x844-100-navigation`, page: `${lang}-${s}`, viewport: [390, 844], action: 'steps',
      steps: [{ record: 'links', js: CLICK_ALL_LINKS }, { focus: '.dbar__back', key: 'Enter', record: 'enter-back' }], assert: NAV_ASSERT }))),
    // Data preservation: the screen's own record, with its assertions.
    ...Object.entries(o.dataAssert).flatMap(([page, assert]) => KEY_SIZES.map(([w, h, scale]) => ({
      name: `${page}-${w}x${h}-${scale}-data`, page, viewport: [w, h], scale, action: 'steps', steps: [{ record: 'data', js: o.data }],
      assert: assert.map(([label, fn]) => [label, (r) => fn(r.data)]) }))),
    // Reduced motion.
    { name: `en-${o.scenarios[0]}-390x844-100-reduced-motion`, page: `en-${o.scenarios[0]}`, viewport: [390, 844], action: 'scroll', media: { reducedMotion: true } },
    { name: 'en-states-390x844-100-reduced-motion', page: 'en-states', viewport: [390, 844], action: 'segments', media: { reducedMotion: true } },
    ...(o.extraRuns || []),
  ];
  return {
    name: o.name, baseline: o.baseline, pilot: o.pilot,
    viewports: [[390, 844], [320, 693]], textScales: [100, 200],
    pages, runs, stateProbe: NAV_STATE,
    probes: { dbar: DBAR, ...(o.probes || {}) },
    saveShots: 'first',
  };
}
